struct Guard lock ()
{
  <retval>->a = 0;
  return <retval>;
}


void bar ()
{
  struct Guard foo;

  try
    {
      foo = lock (); [return slot optimization]
      try
        {

        }
      finally
        {
          Guard::~Guard (&foo);
        }
    }
  finally
